const blocklist = ['remote zest jobs', 'synergisticit'];
return $input.all().filter(item => {
  const employer = (item.json.employer_name || '').toLowerCase();
  const publisher = (item.json.job_publisher || '').toLowerCase();
  return !blocklist.some(b => employer.includes(b) || publisher.includes(b));
});

const keywords = ['python', 'dev', 'developer', 'desenvolvedor', 'programmer', 'programador', 'automation', 'automação', 'automacao', 'ia', 'ai', 'llm', 'agent', 'agente', 'data', 'dados', 'backend', 'software engineer', 'engenheiro de software', 'engenharia', 'n8n', 'machine learning', 'analyst', 'analista', 'estágio', 'estagio', 'rpa', 'integrações', 'integracoes', 'rag', 'sql'];
return $input.all().filter(item => {
  const title = (item.json.job_title || '').toLowerCase();
  return keywords.some(k => title.includes(k));
});
